INSERT INTO `wp_posts` VALUES (48,1,'2026-08-08 04:56:44','2026-08-08 04:56:44','Công viên Thiên Đường kết hợp cảnh quan sinh thái với không gian tưởng niệm được tổ chức chỉn chu. Hệ thống khuôn viên đa dạng phục vụ nhu cầu riêng của từng gia đình.\r\n\r\nTrang mẫu minh họa cách quản lý nhiều ảnh và thông tin dự án mà không cần sửa nội dung trong file PHP.','Công viên Thiên Đường','Quần thể sinh thái tâm linh được quy hoạch trang nghiêm, xanh và chú trọng giá trị bền vững cho nhiều thế hệ.','publish','closed','closed','','cong-vien-thien-duong','','','2026-08-12 05:01:56','2026-08-12 05:01:56','',0,'http://reco-group.local/du-an/cong-vien-thien-duong/',3,'reco_project','',0);
